package io.github.dream07code.innovationspace.scoring; import java.util.List; public class ScoringProviderRegistry {private final ScoringProperties props;private final List<ReportScoringProvider> providers;public ScoringProviderRegistry(ScoringProperties p,List<ReportScoringProvider> providers){this.props=p;this.providers=providers;}public ReportScoringProvider provider(){if(!props.isEnabled())throw new IllegalStateException("AI scoring disabled");if("mock".equals(props.getProvider()))return providers.stream().filter(x->x instanceof MockReportScoringProvider).findFirst().orElseThrow();throw new IllegalArgumentException("Unknown AI provider");}}
